WITH department_stats AS (SELECT dept_id, MAX(salary) - MIN(salary) AS salary_range FROM employees WHERE YEAR(hire_date) >= 2023 GROUP BY dept_id) SELECT departments.id, departments.budget, departments.dept_name, department_stats.salary_range FROM departments LEFT OUTER JOIN department_stats ON departments.id = department_stats.dept_id WHERE department_stats.salary_range >= 38 ORDER BY departments.budget DESC;
